export const cards=majors.map((m,i)=>({id:i,name:m[0],vi:m[1],keywords:m[2],upright:m[3],reversed:m[4],action:m[5],symbol:m[6],suit:'major',group:'Ẩn chính',element:['Khí','Đất','Nước','Lửa'][i%4],color:['#9a704d','#536f75','#77719a','#887b49'][i%4]}));
for (const s of suits) for(const [i,r] of ranks.entries()) cards.push({id:cards.length,name:`${r[0]} of ${s[0]}`,vi:`${r[1]} ${s[1]}`,keywords:`${r[2]}, ${s[4]}`,upright:`${r[3]} trong lĩnh vực ${s[4]}. ${s[5]}`,reversed:`${s[6]} Ở giai đoạn ${r[2]}, hãy điều chỉnh nhịp độ và xem lại động cơ của mình.`,action:`${r[4]}.`,symbol:s[3],suit:s[0].toLowerCase(),group:`Bộ ${s[1]}`,element:s[2],color:s[7],rank:i});
export const topics=[
['love','♡','Tình yêu','Tôn trọng sự tự nguyện, ranh giới và giao tiếp trực tiếp. Lá bài không thể xác nhận cảm xúc bí mật của người khác.','Hãy nói rõ một mong muốn thay vì chờ người kia tự hiểu.'],
['crush','✧','Crush / Thầm thích','Nhìn vào hành vi có thể quan sát thay vì diễn giải một tín hiệu đơn lẻ. Dành chỗ cho câu trả lời của người kia.','Bắt đầu một cuộc trò chuyện tự nhiên, không gây áp lực.'],
['ex','☾','Người yêu cũ','Trải nghiệm cũ cần được nhìn trong bối cảnh hiện tại. Việc quay lại chỉ có ý nghĩa khi cả hai tự nguyện và vấn đề cũ được trao đổi.','Viết ra điều đã thay đổi và điều bạn không muốn lặp lại.'],
['partner','♥','Người yêu hiện tại','Chất lượng kết nối đến từ sự nhất quán và cách hai người giải quyết khác biệt. Đừng thay cuộc trò chuyện bằng phỏng đoán.','Hẹn một cuộc trao đổi bình tĩnh về kỳ vọng của cả hai.'],
['future-love','❀','Người yêu tương lai','Tập trung vào giá trị và kiểu kết nối bạn mong muốn. Tarot không xác định danh tính hoặc ngày gặp một người cụ thể.','Tham gia một hoạt động phù hợp sở thích và mở rộng kết nối.'],
['ambiguous','∞','Mối quan hệ mập mờ','Sự rõ ràng thường cần một câu hỏi trực tiếp. Bạn có quyền đặt ranh giới nếu mối quan hệ làm mình liên tục bất an.','Hỏi rõ mong muốn và giới hạn của mối quan hệ.'],
['someone','☽','Người đang nghĩ đến','Bạn không thể biết chắc suy nghĩ của người khác chỉ từ trải bài. Dùng thông điệp để nhìn lại cách bạn đang tương tác.','Đối chiếu điều bạn cảm nhận với hành vi thực tế.'],
['marriage','⚭','Hôn nhân','Chia sẻ trách nhiệm và lắng nghe nhu cầu khác biệt giúp xây nền tảng chung. Tìm hỗ trợ chuyên môn nếu xung đột vượt khả năng tự giải quyết.','Chọn một vấn đề cụ thể để cùng bàn cách cải thiện.'],
['career','♜','Công việc','Đối chiếu thông điệp với kỹ năng, nguồn lực và phản hồi thực tế. Một kế hoạch có tiêu chí đo lường giúp bạn kiểm tra tiến triển.','Chọn một đầu việc quan trọng có thể hoàn thành hôm nay.'],
['job','➶','Xin việc','Tập trung vào hồ sơ, kỹ năng và yêu cầu thực tế của vị trí. Trải bài không bảo đảm kết quả tuyển dụng.','Điều chỉnh một phần CV cho vị trí bạn định ứng tuyển.'],
['money','✵','Tài chính','Dùng dữ liệu thu chi và khả năng chịu rủi ro để quyết định. Thông điệp này không phải khuyến nghị đầu tư hay dự báo lợi nhuận.','Rà soát một khoản chi và cập nhật ngân sách thực tế.'],
['study','✎','Học tập','Cách học và phản hồi từ bài làm cho biết nhiều hơn việc đoán kết quả. Chia mục tiêu thành các buổi học đủ nhỏ để duy trì.','Dành 25 phút ôn phần bạn đang yếu nhất.'],
['abroad','⌁','Du học','Kế hoạch cần được đối chiếu với điều kiện tuyển sinh, ngân sách và khả năng thích nghi. Chuẩn bị thông tin trước khi cam kết.','Kiểm tra một yêu cầu chính thức từ trường bạn quan tâm.'],
['family','⌂','Gia đình','Mỗi người có một nhu cầu riêng. Tìm cách nói rõ điều bạn có thể hỗ trợ và những giới hạn cần được tôn trọng.','Hỏi thăm một thành viên bằng một câu hỏi cởi mở.'],
['conflict','⚖','Giải quyết xung đột','Tách hành vi cụ thể khỏi đánh giá con người. Một thỏa thuận nhỏ có thể thực tế hơn việc cố giải quyết mọi bất đồng cùng lúc.','Dùng câu bắt đầu bằng “Tôi cảm thấy… và tôi cần…”.'],
['health','❧','Sức khỏe','Thông điệp chỉ gợi ý chăm sóc bản thân, không dùng để chẩn đoán hay dự đoán bệnh. Khi có triệu chứng, hãy trao đổi với nhân viên y tế.','Chọn giờ nghỉ, bữa ăn hoặc hoạt động nhẹ phù hợp với bạn.'],
['self','◎','Định hướng bản thân','Nhìn lại điều bạn coi trọng và phân biệt nó với kỳ vọng bên ngoài. Thay đổi nhỏ, nhất quán giúp bạn kiểm tra hướng đi.','Viết ba điều bạn muốn ưu tiên trong tuần này.']
].map(t=>({id:t[0],icon:t[1],name:t[2],context:t[3],action:t[4]}));
export function questions(t){const n=topics.find(x=>x.id===t)?.name.toLowerCase()||'bản thân';return [`Tôi nên tập trung vào điều gì về ${n} lúc này?`,`Điều gì đang cản trở tôi trong ${n}?`,`Tôi có thể làm gì để cải thiện ${n}?`,`Tôi cần cân nhắc gì trước quyết định về ${n}?`,`Bài học nào tôi có thể rút ra về ${n}?`];}
