export const articles=[
{slug:'bat-dau-voi-tarot',title:'Bắt đầu với Tarot: một khoảng lặng cho chính mình',tag:'Dành cho người mới',icon:'☾',intro:'Bạn không cần thuộc lòng 78 lá bài để bắt đầu một trải nghiệm có ý nghĩa.',sections:[['Tarot có thể giúp gì?','Các biểu tượng tạo ra một điểm tựa để bạn kể lại vấn đề, nhìn ra cảm xúc và đặt câu hỏi mới. Ý nghĩa xuất hiện trong quá trình suy ngẫm, không phải một lời bảo đảm về tương lai.'],['Bắt đầu với một câu hỏi mở','Thay “Chuyện đó chắc chắn xảy ra không?”, hãy thử “Tôi cần hiểu gì trước khi quyết định?”. Câu hỏi tốt hướng sự chú ý về điều bạn có thể quan sát và hành động.'],['Đọc, ghi lại và kiểm tra','Rút một lá, đọc cả thông điệp lẫn lời nhắc, rồi ghi một hành động nhỏ. Sau vài ngày, xem lại điều gì hữu ích và điều gì không phù hợp bối cảnh.']]},
{slug:'cach-dat-cau-hoi',title:'Đặt câu hỏi để nhận được một góc nhìn rõ ràng hơn',tag:'Hướng dẫn',icon:'✧',intro:'Một câu hỏi cụ thể tạo nền tảng cho một trải bài dễ suy ngẫm.',sections:[['Nêu bối cảnh','Bạn có thể ghi mục tiêu, lựa chọn đang cân nhắc và khoảng thời gian. Tránh đưa thông tin nhận diện hoặc dữ liệu riêng tư của người khác.'],['Giữ quyền chủ động','Thay “Họ có yêu tôi không?” bằng “Tôi cần trao đổi điều gì để hiểu rõ mối quan hệ?”. Trải bài không đọc được suy nghĩ của người khác.'],['Từ câu hỏi đến hành động','Sau khi đọc, hãy chọn một việc có thể làm và một dữ kiện cần xác minh. Bạn không cần cố gắng ép thông điệp khớp mọi chi tiết.']]},
{slug:'trai-ba-la',title:'Cách đọc trải bài 3 lá: bối cảnh, hiện tại và hướng đi',tag:'Thực hành',icon:'△',intro:'Ba vị trí giúp bạn sắp xếp câu chuyện mà không biến trải bài thành một dự báo chắc chắn.',sections:[['Lá 1: Bối cảnh','Quan sát một trải nghiệm hoặc thói quen có thể đang ảnh hưởng đến vấn đề. Hãy xem đây là giả thuyết để suy ngẫm.'],['Lá 2: Hiện tại','Nhìn vào nguồn lực, khó khăn và cảm xúc đang có. Đối chiếu thông điệp với những gì bạn biết chắc.'],['Lá 3: Hướng đi','Đọc như một hướng hành động có thể thử. Tương lai còn phụ thuộc vào lựa chọn, hoàn cảnh và người khác.']]},
{slug:'la-nguoc',title:'Lá đảo ngược có phải là điềm xấu?',tag:'Kiến thức Tarot',icon:'↕',intro:'Một lá ngược có thể gợi ý sự trì hoãn, mất cân bằng hoặc điều đang diễn ra trong nội tâm.',sections:[['Không chia bài thành tốt và xấu','Một biểu tượng tích cực vẫn có mặt cần thận trọng. Một lá khó cũng có thể chỉ ra nơi bạn có thể điều chỉnh.'],['Đọc theo bối cảnh','Trong ứng dụng, lá ngược có nội dung riêng, nhưng bạn vẫn là người quyết định thông điệp có phù hợp vấn đề hay không.'],['Không rút lại đến khi vừa ý','Nếu câu trả lời chưa dễ chịu, hãy ghi điều khiến bạn phản ứng và suy nghĩ thêm. Rút nhiều lần liên tiếp không làm tăng độ chắc chắn.']]},
{slug:'bon-bo-an-phu',title:'Bốn bộ Ẩn phụ: Gậy, Cốc, Kiếm và Tiền',tag:'Thư viện',icon:'✵',intro:'56 lá Ẩn phụ tập trung vào những trải nghiệm đời thường.',sections:[['Gậy và Cốc','Gậy liên quan đến động lực, ý tưởng và sự chủ động. Cốc hướng đến cảm xúc, sự gắn kết và cách bạn chăm sóc mối quan hệ.'],['Kiếm và Tiền','Kiếm gợi suy nghĩ, giao tiếp và sự thật. Tiền nhắc đến nền tảng thực tế như kỹ năng, thời gian, công việc và nguồn lực.'],['Con số và lá hoàng gia','Các lá từ Át đến Mười mô tả những giai đoạn trải nghiệm. Tiểu Đồng, Hiệp Sĩ, Hoàng Hậu và Nhà Vua có thể được đọc như các cách tiếp cận, không nhất thiết là người cụ thể.']]},
{slug:'nhat-ky-tarot',title:'Viết nhật ký Tarot mà không lệ thuộc vào trải bài',tag:'Chăm sóc bản thân',icon:'✎',intro:'Ghi chép giúp bạn nhận ra điều hữu ích qua thời gian.',sections:[['Ghi điều thực sự có ích','Lưu câu hỏi, thông điệp khiến bạn chú ý và một hành động bạn chọn. Bổ sung kết quả thực tế khi có.'],['Giữ khoảng cách lành mạnh','Bạn có thể bỏ qua nội dung không phù hợp. Đừng dùng Tarot thay thế chăm sóc y tế, tư vấn pháp lý hoặc quyết định tài chính có căn cứ.'],['Quyền riêng tư trong ứng dụng','Nhật ký được lưu trong trình duyệt trên thiết bị này, không có đồng bộ tài khoản. Bạn có thể xuất JSON để sao lưu hoặc xóa nhật ký bất kỳ lúc nào.']]}
];
// Card-specific traditional themes, independently phrased for this application.
const minorThemes={
wands:[
['Tia lửa sáng tạo','Một ý tưởng khiến bạn muốn bắt tay ngay vào việc mới. Hãy thử quy mô nhỏ để biết sự hào hứng có thể chuyển thành cam kết bền vững hay không.','Ý tưởng có thể chưa có đủ thời gian, nguồn lực hoặc động lực để bắt đầu. Bạn có thể điều chỉnh kế hoạch thay vì ép mình tăng tốc.'],
['Lập kế hoạch','Bạn đang nhìn xa hơn phạm vi quen thuộc và cân nhắc một hướng phát triển. Chọn tiêu chí rõ ràng để so sánh việc ở lại với bước ra ngoài.','Sợ thay đổi hoặc kế hoạch quá mơ hồ có thể giữ bạn đứng yên. Thu hẹp lựa chọn và xác định một điều cần tìm hiểu thêm.'],
['Tầm nhìn rộng','Những bước chuẩn bị ban đầu đang cho bạn cơ hội mở rộng. Quan sát phản hồi từ thực tế và sẵn sàng hợp tác với người ở ngoài vòng quen thuộc.','Tiến độ chậm hoặc kỳ vọng mở rộng quá nhanh có thể làm bạn sốt ruột. Kiểm tra lại thời hạn và phần phụ thuộc vào người khác.'],
['Cộng đồng và ăn mừng','Một cột mốc, sự gặp gỡ hoặc cảm giác thuộc về có thể tiếp thêm năng lượng. Dành thời gian ghi nhận công sức và những người đã hỗ trợ bạn.','Cảm giác chưa được đón nhận hoặc bất đồng trong tập thể cần được lắng nghe. Sự hòa hợp không đòi hỏi bạn phải bỏ qua nhu cầu riêng.'],
['Cạnh tranh và khác biệt','Nhiều ý kiến hoặc mục tiêu đang va chạm. Nếu cùng thống nhất luật chơi và cách trao đổi, sự khác biệt có thể giúp làm rõ vấn đề.','Bạn có thể đang né bất đồng hoặc mệt vì tranh hơn thua. Chọn việc đáng trao đổi và dừng những cuộc cạnh tranh không có mục đích.'],
['Ghi nhận thành quả','Nỗ lực có thể đang được người khác nhìn thấy. Hãy nhận sự ghi nhận đồng thời nhớ đến sự hỗ trợ và những việc vẫn cần hoàn thiện.','Nhu cầu được công nhận có thể đang lấn át giá trị công việc. Đối chiếu tiến bộ với tiêu chí của bạn thay vì chỉ dựa vào lời khen.'],
['Giữ lập trường','Bạn có thể cần bảo vệ một ưu tiên hoặc ranh giới khi gặp nhiều ý kiến trái chiều. Chọn lập luận và dữ kiện thay vì phản ứng phòng thủ.','Luôn ở tư thế chống đỡ có thể khiến bạn kiệt sức. Xác định điều nào thật sự cần giữ và điều nào có thể thương lượng.'],
['Thông tin và tốc độ','Nhiều việc hoặc thông tin đang đến gần nhau. Làm rõ thứ tự ưu tiên và xác nhận chi tiết trước khi đưa ra phản hồi nhanh.','Sự chậm trễ, hiểu lầm hoặc nhịp độ quá gấp có thể làm bạn mất hướng. Kiểm tra kênh liên lạc và thống nhất lại thời hạn.'],
['Bền bỉ và cảnh giác','Bạn đã đi qua một chặng khó và có kinh nghiệm bảo vệ mình. Giữ ranh giới nhưng đừng mặc định tình huống mới sẽ lặp lại tổn thương cũ.','Căng thẳng kéo dài có thể làm bạn luôn đề phòng. Nghỉ ngơi và tìm sự hỗ trợ là một phần của khả năng đi tiếp.'],
['Gánh nặng trách nhiệm','Bạn có thể đang ôm quá nhiều đầu việc. Phân biệt trách nhiệm thực sự của mình với điều bạn nhận thêm vì khó nói lời từ chối.','Đây có thể là lúc giảm tải hoặc chia việc. Buông bớt một cam kết không có nghĩa là phủ nhận công sức trước đó.'],
['Khám phá ý tưởng','Tinh thần tò mò mời bạn học bằng thử nghiệm. Cho phép mình chưa thành thạo và quan sát điều khiến bạn muốn tiếp tục tìm hiểu.','Sự háo hức thiếu định hướng có thể làm bạn bắt đầu nhiều việc nhưng bỏ dở. Chọn một thử nghiệm đủ nhỏ để hoàn thành.'],
['Nhiệt huyết hành động','Bạn có động lực bước ra ngoài vùng quen thuộc. Hãy tận dụng sự can đảm nhưng kiểm tra cam kết và ảnh hưởng trước khi hành động mạnh.','Nóng vội, khó chịu hoặc thiếu kiên trì có thể làm năng lượng trở thành xung đột. Dừng lại để điều chỉnh hướng đi.'],
['Tự tin và ấm áp','Bạn có thể tạo ảnh hưởng bằng sự cởi mở và cách khuyến khích người khác. Tự tin không cần phải giống một hình mẫu bên ngoài.','So sánh, ghen tị hoặc sợ bị nhìn thấy có thể làm bạn thu mình. Quay lại điều bạn làm tốt và những ranh giới giúp bạn an tâm.'],
['Tầm nhìn và lãnh đạo','Một hướng đi rõ ràng cần được chuyển thành kế hoạch có người chịu trách nhiệm. Dẫn dắt bằng cách tạo điều kiện để người khác chủ động.','Kỳ vọng quá cao hoặc cách điều hành cứng nhắc có thể làm tập thể mất động lực. Lắng nghe phản hồi trước khi thúc ép.']
],
cups:[
['Cởi mở cảm xúc','Một cảm xúc mới hoặc nhu cầu kết nối đang được bạn nhận ra. Cho nó không gian phát triển mà không vội đặt tên hay đòi hỏi kết quả.','Cảm xúc bị dồn nén hoặc nguồn lực tinh thần cạn có thể khiến bạn khó mở lòng. Chăm sóc mình trước khi cố cho đi nhiều hơn.'],
['Kết nối hai chiều','Sự gặp gỡ có ý nghĩa cần có tôn trọng và trao đổi từ cả hai bên. Nhìn vào cách bạn và người kia lắng nghe, cam kết và xử lý khác biệt.','Một bên có thể đang cho đi nhiều hơn hoặc chưa được lắng nghe. Làm rõ kỳ vọng thay vì giả định hai người muốn cùng một điều.'],
['Tình bạn và sẻ chia','Một nhóm bạn hoặc cộng đồng có thể đem lại cảm giác được nâng đỡ. Đón nhận sự hỗ trợ và tạo chỗ cho những niềm vui chung.','Khác biệt trong nhóm hoặc cảm giác bị đứng ngoài cần được nhìn nhận. Giữ ranh giới với những tương tác khiến bạn mất năng lượng.'],
['Khoảng lặng cảm xúc','Bạn có thể đang chán nản hoặc không thấy hấp dẫn với những lựa chọn sẵn có. Dành thời gian nhận diện điều mình thực sự cần.','Bạn có thể bắt đầu nhìn thấy một khả năng từng bỏ qua. Hãy thử tìm hiểu thêm thay vì buộc mình phải cảm thấy hứng thú ngay.'],
['Mất mát và điều còn lại','Một sự thất vọng xứng đáng được thừa nhận. Sau khi cho mình thời gian buồn, hãy nhìn lại những nguồn hỗ trợ vẫn hiện diện.','Bạn có thể đang học cách chấp nhận điều đã qua và nhận sự giúp đỡ. Hồi phục không nhất thiết diễn ra đều đặn từng ngày.'],
['Ký ức và thân thuộc','Một kỷ niệm hoặc giá trị từ quá khứ có thể đem lại sự ấm áp. Phân biệt điều mình trân trọng với việc lý tưởng hóa chuyện cũ.','Quá khứ có thể đang chi phối cách bạn nhìn hiện tại. Bạn có thể giữ bài học mà không cần quay lại cùng một hoàn cảnh.'],
['Nhiều khả năng','Các lựa chọn có thể hấp dẫn nhưng chưa được kiểm tra. Tách mong muốn khỏi điều kiện thực tế trước khi đầu tư thời gian và hy vọng.','Một vài lựa chọn đang trở nên rõ hơn khi bạn kiểm chứng thông tin. Đừng để nhu cầu chắc chắn tuyệt đối cản bước thử nghiệm.'],
['Rời điều không còn phù hợp','Bạn có thể nhận ra một hoàn cảnh không còn đáp ứng nhu cầu sâu hơn. Trước khi rời đi, làm rõ điều đã thử và điều mình đang tìm kiếm.','Do dự giữa ở lại và rời đi có thể phản ánh một nhu cầu chưa được gọi tên. Cân nhắc cả giới hạn lẫn nguồn lực hỗ trợ.'],
['Hài lòng và biết đủ','Nhìn lại điều đang làm bạn thấy đủ đầy và những nỗ lực đã đóng góp cho nó. Niềm vui bền hơn khi không phụ thuộc hoàn toàn vào sự công nhận.','Một mong muốn đạt được có thể chưa mang lại cảm giác như bạn kỳ vọng. Hỏi lại nhu cầu phía sau mục tiêu đó.'],
['Gắn kết và giá trị chung','Một cảm giác thuộc về có thể đến từ cách mọi người chia sẻ và chăm sóc nhau. Hãy xây dựng sự an toàn bằng những hành động nhất quán.','Hình ảnh hòa thuận có thể đang che khuất nhu cầu khác biệt. Một cuộc trò chuyện thành thật hữu ích hơn cố giữ vẻ hoàn hảo.'],
['Nhạy cảm và tò mò','Bạn có thể đang nhận ra một cảm xúc tinh tế hoặc một cách thể hiện sáng tạo. Lắng nghe nó mà không vội kết luận thay người khác.','Nhạy cảm quá mức hoặc khó gọi tên cảm xúc có thể khiến bạn hiểu lầm tín hiệu. Tìm một cách diễn đạt đơn giản và trực tiếp.'],
['Lý tưởng và lời mời','Sự lãng mạn hoặc cảm hứng có thể thúc đẩy bạn bày tỏ. Kiểm tra xem hành động thực tế có nhất quán với những lời đẹp đẽ không.','Một lý tưởng hấp dẫn có thể chưa đi kèm cam kết. Chú ý sự nhất quán thay vì chỉ đánh giá theo cảm xúc nhất thời.'],
['Lắng nghe và đồng cảm','Sự thấu cảm giúp bạn hiểu cảm xúc mà không cần gánh thay mọi vấn đề. Giữ ranh giới để việc chăm sóc người khác không làm bạn cạn kiệt.','Bạn có thể đang hấp thụ quá nhiều cảm xúc từ xung quanh. Tách trách nhiệm của mình khỏi điều thuộc về người khác.'],
['Vững vàng cảm xúc','Bạn có thể giữ bình tĩnh và trao đổi có chừng mực trước tình huống khó. Cân bằng cảm nhận với đánh giá thực tế.','Kìm nén hoặc dùng cảm xúc để kiểm soát có thể làm kết nối mất cân bằng. Chọn cách nói rõ nhu cầu mà không gây áp lực.']
],
swords:[
['Rõ ràng và sự thật','Một cách hiểu mới có thể giúp bạn nhìn rõ vấn đề. Sử dụng thông tin được kiểm chứng và nói điều cần nói bằng ngôn ngữ chính xác.','Thiếu thông tin hoặc suy nghĩ chưa được sắp xếp có thể làm kết luận lệch đi. Kiểm tra dữ kiện trước khi khẳng định.'],
['Lưỡng lự trước lựa chọn','Bạn có thể đang cần thêm thông tin hoặc sợ hệ quả của một quyết định. Gọi tên tiêu chí quan trọng thay vì tiếp tục gạt vấn đề sang bên.','Việc trì hoãn có thể đang làm áp lực tăng lên. Thu hẹp lựa chọn và xác định mốc thời gian hợp lý để quyết định.'],
['Tổn thương và nhận diện','Một sự thật khó hoặc lời nói khiến bạn đau cần được thừa nhận. Tìm sự hỗ trợ và cho mình thời gian thay vì ép phải ổn ngay.','Bạn có thể đang tìm cách xử lý tổn thương cũ. Tha thứ hoặc tiếp tục kết nối là lựa chọn riêng, không phải nghĩa vụ.'],
['Nghỉ ngơi và hồi sức','Một khoảng tạm dừng có chủ đích giúp bạn sắp xếp suy nghĩ. Đừng đợi đến khi kiệt sức mới cho phép mình nghỉ.','Nhịp nghỉ có thể chưa đủ hoặc việc tạm dừng đang trở thành né tránh. Xem lại nhu cầu cơ thể và cách quay lại từng bước.'],
['Cái giá của hơn thua','Một chiến thắng có thể không đáng nếu làm mất sự tin cậy. Xem lại mục tiêu cuộc trao đổi và điều cả hai bên có thể chấp nhận.','Bạn có thể đang muốn dừng tranh cãi hoặc sửa một rạn nứt. Sự hòa giải cần hành động rõ ràng và thiện chí từ các bên.'],
['Chuyển sang vùng yên hơn','Một thay đổi chậm có thể giúp bạn rời trạng thái căng thẳng. Mang theo kinh nghiệm cần thiết mà không phải giữ mọi gánh nặng cũ.','Điều chưa được giải quyết có thể khiến bạn khó bước tiếp. Nhận diện việc cần khép lại và nguồn hỗ trợ cần tìm.'],
['Chiến lược và minh bạch','Bạn cần tính toán cách hành động và bảo vệ thông tin phù hợp. Đồng thời xem xét sự minh bạch và hệ quả của việc giữ kín.','Một thông tin cần được làm rõ hoặc một cách né tránh đã bộc lộ giới hạn. Thành thật với phần trách nhiệm của mình giúp sửa hướng.'],
['Giới hạn và niềm tin','Bạn có thể cảm thấy ít lựa chọn hơn thực tế. Tách ràng buộc thật khỏi điều mình mặc định, rồi tìm một bước nhỏ có thể chủ động.','Bạn có thể bắt đầu nhận ra một lựa chọn từng không nhìn thấy. Thử điều chỉnh niềm tin bằng trải nghiệm an toàn và cụ thể.'],
['Lo âu và suy nghĩ lặp','Một nỗi lo có thể đang chiếm nhiều không gian tinh thần. Viết nó ra, kiểm tra điều đã xảy ra và tìm hỗ trợ khi cần.','Bạn có thể đang dần chia sẻ điều khiến mình lo. Không cần tự xử lý mọi thứ; hỗ trợ phù hợp có thể giảm gánh nặng.'],
['Khép lại một chặng khó','Một hoàn cảnh có thể đã đi đến giới hạn và cần dừng lại. Ưu tiên hồi phục và nguồn lực thực tế trước khi lên kế hoạch quá xa.','Bạn có thể đang từng bước đứng dậy sau một giai đoạn khó. Hồi phục cần thời gian và không đòi hỏi bạn lập tức trở lại nhịp cũ.'],
['Tìm hiểu và đặt câu hỏi','Tò mò và khả năng quan sát giúp bạn tìm thông tin mới. Kiểm tra nguồn và tránh chia sẻ kết luận khi mới có một phần câu chuyện.','Thông tin rời rạc hoặc lời nói thiếu cân nhắc có thể tạo hiểu lầm. Chậm lại trước khi trả lời hoặc chuyển tiếp tin.'],
['Quyết đoán và tốc độ','Một mục tiêu rõ có thể thúc đẩy hành động nhanh. Cần lắng nghe phản hồi để tốc độ không làm bạn bỏ qua con người và chi tiết.','Vội vàng, căng thẳng hoặc tranh luận quá mạnh có thể cản mục tiêu. Tạm dừng để kiểm tra cách tiếp cận.'],
['Rõ ràng và ranh giới','Kinh nghiệm giúp bạn nhận diện điều phù hợp và nói rõ giới hạn. Sự thẳng thắn hữu ích nhất khi đi cùng tôn trọng.','Phòng vệ hoặc phê bình quá sắc có thể làm đối thoại đóng lại. Nói về hành vi cụ thể thay vì đánh giá toàn bộ con người.'],
['Lý trí và trách nhiệm','Bạn được mời gọi đánh giá có hệ thống, dùng bằng chứng và giữ nguyên tắc công bằng. Nói rõ cơ sở của quyết định để người khác hiểu.','Lý lẽ có thể đang được dùng để áp đặt hoặc che đi thiên kiến. Kiểm tra giả định và chừa chỗ cho thông tin mới.']
],
pentacles:[
['Cơ hội thực tế','Một cơ hội về kỹ năng, công việc hoặc nguồn lực cần được nuôi dưỡng bằng hành động đều đặn. Xem xét điều kiện trước khi cam kết.','Một cơ hội có thể chưa có nền tảng hoặc điều khoản rõ ràng. Kiểm tra chi phí, thời gian và tính khả thi thay vì chỉ nhìn lợi ích.'],
['Cân đối nguồn lực','Bạn có thể đang xoay xở nhiều trách nhiệm cùng lúc. Xếp thứ tự ưu tiên và tính cả khoảng dự phòng cho những việc phát sinh.','Sự quá tải hoặc phân bổ thiếu cân bằng có thể làm bạn khó duy trì nhịp. Giảm bớt một cam kết để bảo vệ phần việc thiết yếu.'],
['Hợp tác và tay nghề','Kỹ năng của mỗi người bổ sung cho nhau khi vai trò và tiêu chuẩn được làm rõ. Chủ động xin phản hồi để nâng chất lượng công việc.','Thiếu phối hợp hoặc kỳ vọng không thống nhất có thể gây lãng phí. Thống nhất phạm vi, người phụ trách và cách nghiệm thu.'],
['Giữ gìn và an toàn','Nhu cầu ổn định khiến bạn muốn bảo vệ điều đã có. Phân biệt sự thận trọng hợp lý với việc giữ chặt đến mức không thể điều chỉnh.','Bạn có thể đang học cách chia sẻ hoặc sắp xếp lại nguồn lực. Hãy làm điều đó trong giới hạn đủ an toàn cho bản thân.'],
['Thiếu hụt và hỗ trợ','Một khó khăn thực tế có thể khiến bạn cảm thấy đơn độc. Tìm hiểu các nguồn hỗ trợ và trao đổi rõ nhu cầu thay vì tự gánh tất cả.','Một lối hỗ trợ hoặc phương án phục hồi có thể đang dần xuất hiện. Kiểm tra điều kiện và chọn bước phù hợp khả năng của bạn.'],
['Cho đi và nhận lại','Sự hỗ trợ bền vững cần có minh bạch và tôn trọng. Xem xét liệu việc trao đổi có tạo sự phụ thuộc hoặc chênh lệch quyền quyết định không.','Một mối trao đổi có thể đang lệch cán cân. Làm rõ điều kiện, khả năng hoàn trả hoặc giới hạn bạn có thể giúp.'],
['Kiên nhẫn đánh giá','Bạn đã đầu tư công sức và cần thời gian xem kết quả. Đánh giá bằng tiến độ thực tế thay vì chỉ tiếp tục vì tiếc công đã bỏ ra.','Nỗ lực có thể đang đi vào hướng ít hiệu quả. Kiểm tra mục tiêu và cân nhắc điều chỉnh trước khi đầu tư thêm nguồn lực.'],
['Luyện tập và chất lượng','Sự lặp lại có chủ đích giúp nâng tay nghề. Chọn một kỹ năng và cách nhận phản hồi để biết mình đang tiến bộ ở đâu.','Cầu toàn, làm máy móc hoặc bỏ qua nền tảng có thể hạn chế tiến bộ. Điều chỉnh cách luyện tập thay vì chỉ tăng số giờ.'],
['Tự chủ và thành quả','Bạn có thể ghi nhận sự độc lập được xây bằng kỹ năng và thói quen bền bỉ. Tận hưởng thành quả mà vẫn giữ kế hoạch phù hợp.','Đánh đổi quá nhiều để duy trì hình ảnh thành công có thể làm bạn mệt. Định nghĩa lại điều đủ đầy theo nhu cầu thực tế.'],
['Nền tảng dài hạn','Một kế hoạch bền vững cần nhìn đến trách nhiệm, giá trị chung và những người liên quan. Củng cố nền tảng thay vì chỉ theo lợi ích ngắn hạn.','Khác biệt về nguồn lực hoặc kỳ vọng gia đình có thể cần được làm rõ. Không giả định mọi người đều có chung mục tiêu.'],
['Học hỏi thiết thực','Một mục tiêu mới cần kỹ năng nền tảng và lịch thực hiện cụ thể. Tinh thần học việc giúp bạn tiến bộ mà không phải chứng minh mọi thứ ngay.','Một ý tưởng thực tế có thể đang bị trì hoãn vì thiếu kế hoạch. Chọn một bước học hoặc thực hành đủ nhỏ để bắt đầu.'],
['Bền bỉ và trách nhiệm','Sự cẩn thận, đúng hẹn và đều đặn giúp tạo sự tin cậy. Bạn có thể đi chậm miễn là biết mình đang tiến về đâu.','Một nếp làm việc quá cứng có thể khiến bạn khó thích nghi. Xem lại quy trình và thử một điều chỉnh có thể đo lường.'],
['Chăm sóc nền tảng','Sự quan tâm có thể thể hiện qua việc sắp xếp không gian, thời gian và nguồn lực. Chăm sóc bản thân là nền tảng để hỗ trợ người khác.','Gánh việc thực tế cho quá nhiều người có thể khiến bạn bỏ quên mình. Làm rõ giới hạn và phần trách nhiệm có thể chia sẻ.'],
['Quản lý bền vững','Kinh nghiệm cần được dùng để bảo vệ nguồn lực và tạo nền tảng ổn định. Quyết định có trách nhiệm cân nhắc cả hiệu quả và người chịu ảnh hưởng.','Đặt nặng thành quả vật chất hoặc nhu cầu kiểm soát có thể làm mục tiêu mất cân bằng. Xem lại giá trị phía sau việc tích lũy.']
]};
for(const c of cards.filter(c=>c.suit!=='major')){const m=minorThemes[c.suit][c.rank];c.keywords=`${m[0]}, ${c.element.toLowerCase()}`;c.upright=m[1];c.reversed=m[2];}
